const TIMEOUT: Duration = Duration::from_secs(10);
fn diff_fixture_text(right: bool) -> String {
    (0..180)
        .map(|i| {
            if [10, 90, 160].contains(&i) {
                format!("{} change {i}\n", if right { "new" } else { "old" })
            } else {
                format!("context {i}\n")
            }
        })
        .collect()
}
fn checksum_input_rect(
    ctx: &egui::Context,
    key: egui::Id,
    input: &mut egui::RawInput,
) -> Option<egui::Rect> {
    let rect = ctx.data(|data| data.get_temp::<egui::Rect>(key))?;
    if let Some(clip) =
        ctx.data(|data| data.get_temp::<egui::Rect>(egui::Id::new("checksum-sheet-clip")))
        // egui can round the bottom edge by a fraction of a logical pixel at
        // maximum scroll. Require the button interior, not its antialiased edge.
        && !clip.contains_rect(rect.shrink(0.5))
    {
        input.events.push(egui::Event::PointerMoved(egui::pos2(
            clip.center().x,
            clip.max.y - 12.0,
        )));
        input.events.push(egui::Event::MouseWheel {
            unit: egui::MouseWheelUnit::Point,
            phase: egui::TouchPhase::Move,
            delta: egui::vec2(
                0.0,
                if rect.min.y < clip.min.y {
                    120.0
                } else {
                    -120.0
                },
            ),
            modifiers: Default::default(),
        });
        return None;
    }
    Some(rect)
}

